recommendation:
Add a hard upper bound to `setDesiredAPY`:

  uint256 public constant MAX_APY_BPS = 100_000;   // 1000% APY
  function setDesiredAPY(uint256 bps) external onlyOwner {
      require(bps <= MAX_APY_BPS, "APY exceeds cap");
      ...
  }

Alternatively, use a parametric cap that is itself owner-settable but timelocked for, e.g., 7 days, so unbounded APY changes require a meaningful pre-commit window. Document the upper bound in the contract NatSpec so the migrator-staked user knows the worst case before opting in.

A secondary defense is to enforce a cap on cumulative mint per epoch rather than (or in addition to) per-second rate, which prevents long-uninterrupted high-emission periods even at moderate per-second values.

codeSnippet:
// setDesiredAPY — no upper bound on bps:
function setDesiredAPY(uint256 bps) external onlyOwner {
    bool isPreview = !apySetInProgress ||
                    block.number > pendingAPYBlockNumber + 100 ||
                    bps != pendingAPYBps;
    if (isPreview) {
        emit IntendedSetAPY(bps, block.number, msg.sender);
        pendingAPYBps = bps;
        pendingAPYBlockNumber = block.number;
        apySetInProgress = true;
    } else {
        _updatePool();
        uint256 oldAPY = desiredAPYBps;
        desiredAPYBps = bps;          // <-- accepts any uint256
        _updatePhUSDEmissionRate();   // <-- propagates to phUSDPerSecond unchecked
        emit DesiredAPYUpdated(oldAPY, bps);
        apySetInProgress = false;
    }
}

function _updatePhUSDEmissionRate() internal {
    if (totalStaked == 0) { phUSDPerSecond = 0; return; }
    phUSDPerSecond = (totalStaked * desiredAPYBps) / 10000 / SECONDS_PER_YEAR;   // <-- unbounded
}
